-- Institution Email Template module, institution-owned template table, and initial data.
-- Idempotent: rerunning does not duplicate modules, mappings, entitlements, or templates.
BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."InstitutionEmailTemplate"
(
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TemplateName" character varying(150) NOT NULL,
    "TemplateCode" character varying(100),
    "Subject" character varying(250) NOT NULL,
    "Body" text NOT NULL,
    "FromEmail" character varying(150),
    "FromName" character varying(100),
    "CcEmail" text,
    "BccEmail" text,
    "Category" character varying(100),
    "LanguageCode" character varying(10),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp with time zone NOT NULL DEFAULT now(),
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp with time zone,
    "AddedFromIP" character varying(50),
    "UpdatedFromIP" character varying(50),
    CONSTRAINT "FK_InstitutionEmailTemplate_Institution" FOREIGN KEY ("InstitutionId")
        REFERENCES skolenza."Institution" ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_InstitutionEmailTemplate_Institution_TemplateCode"
    ON skolenza."InstitutionEmailTemplate" ("InstitutionId", "TemplateCode");

INSERT INTO skolenza."InstitutionEmailTemplate"
(
    "InstitutionId", "TemplateName", "TemplateCode", "Subject", "Body", "FromEmail", "FromName",
    "CcEmail", "BccEmail", "Category", "LanguageCode", "IsActive", "AddedById", "AddedDateTime",
    "UpdatedById", "UpdatedDateTime", "AddedFromIP", "UpdatedFromIP"
)
SELECT institution."Id", template."TemplateName", template."TemplateCode", template."Subject", template."Body",
       template."FromEmail", template."FromName", template."CcEmail", template."BccEmail", template."Category",
       template."LanguageCode", template."IsActive", template."AddedById", template."AddedDateTime",
       template."UpdatedById", template."UpdatedDateTime", template."AddedFromIP", template."UpdatedFromIP"
FROM skolenza."Institution" institution
CROSS JOIN skolenza."EmailTemplate" template
WHERE NOT EXISTS
(
    SELECT 1 FROM skolenza."InstitutionEmailTemplate" existing
    WHERE existing."InstitutionId" = institution."Id"
      AND existing."TemplateCode" IS NOT DISTINCT FROM template."TemplateCode"
);

INSERT INTO skolenza."Module"
(
    "InstitutionId", "ModuleCode", "ModuleName", "PageName", "DisplayName", "URLPath", "ParentModuleId",
    "IsLeafNode", "IsModuleDisplayInUI", "IsCommonMenu", "IsActive", "ImageIconWeb", "ImageIconMobile",
    "ItemPriority", "Remark", "AddedById", "AddedDateTime", "ModuleScope"
)
SELECT NULL, 'INSTITUTION_EMAIL_TEMPLATE', 'Institution Email Templates', 'institution-email-templates', 'Email Templates',
       '/app/institution-email-templates', parent."Id", TRUE, TRUE, FALSE, TRUE, 'bi bi-envelope-paper', 'mail',
       420, 'Institution-owned email template management.', 1, CURRENT_TIMESTAMP, 1
FROM skolenza."Module" parent
WHERE parent."Id" = 46
  AND parent."ModuleCode" = 'INSTITUTION_EMAIL_CONFIG'
  AND NOT EXISTS (SELECT 1 FROM skolenza."Module" existing WHERE existing."ModuleCode" = 'INSTITUTION_EMAIL_TEMPLATE');

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM skolenza."Module" WHERE "Id" = 46 AND "ModuleCode" = 'INSTITUTION_EMAIL_CONFIG') THEN
        RAISE EXCEPTION 'Parent INSTITUTION_EMAIL_CONFIG Module Id 46 was not found.';
    END IF;
END $$;

INSERT INTO skolenza."ModuleOperationMapping"
(
    "ModuleId", "OperationId", "PageURL", "IconURL", "IsCommonItem", "IsOperational", "Priority",
    "Remark", "IsActive", "AddedById", "AddedDateTime"
)
SELECT module."Id", operation."Id", '/app/institution-email-templates',
       CASE operation."OperationName" WHEN 'Add' THEN 'plus-circle' WHEN 'Update' THEN 'pencil-square'
            WHEN 'Delete' THEN 'trash3' ELSE 'eye' END,
       FALSE, TRUE,
       CASE operation."OperationName" WHEN 'View' THEN 1 WHEN 'Add' THEN 2 WHEN 'Update' THEN 3 ELSE 4 END,
       operation."OperationName" || ' Institution email templates.', TRUE, 1, CURRENT_TIMESTAMP
FROM skolenza."Module" module
JOIN skolenza."Operation" operation ON operation."Id" IN (1, 2, 3, 4) AND operation."IsActive" = TRUE
WHERE module."ModuleCode" = 'INSTITUTION_EMAIL_TEMPLATE'
  AND NOT EXISTS
  (
      SELECT 1 FROM skolenza."ModuleOperationMapping" existing
      WHERE existing."ModuleId" = module."Id" AND existing."OperationId" = operation."Id"
  );

INSERT INTO skolenza."PlanModuleMapping"
    ("SubscriptionPlanId", "ModuleId", "IsActive", "Remark", "AddedById", "AddedDateTime")
SELECT parentMapping."SubscriptionPlanId", child."Id", TRUE, 'Institution Email Templates inherited from Email Settings.',
       1, CURRENT_TIMESTAMP
FROM skolenza."PlanModuleMapping" parentMapping
JOIN skolenza."Module" child ON child."ModuleCode" = 'INSTITUTION_EMAIL_TEMPLATE'
WHERE parentMapping."ModuleId" = 46 AND parentMapping."IsActive" = TRUE
  AND NOT EXISTS
  (
      SELECT 1 FROM skolenza."PlanModuleMapping" existing
      WHERE existing."SubscriptionPlanId" = parentMapping."SubscriptionPlanId" AND existing."ModuleId" = child."Id"
  );

INSERT INTO skolenza."InstitutionEnabledModule"
    ("InstitutionId", "ParentModuleId", "ModuleId", "IsLeafNode", "IsEnabled", "AddedById", "AddedDateTime")
SELECT enabled."InstitutionId", 46, child."Id", TRUE, TRUE, enabled."AddedById", CURRENT_TIMESTAMP
FROM skolenza."InstitutionEnabledModule" enabled
JOIN skolenza."Module" child ON child."ModuleCode" = 'INSTITUTION_EMAIL_TEMPLATE'
WHERE enabled."ModuleId" = 46 AND enabled."IsEnabled" = TRUE
  AND NOT EXISTS
  (
      SELECT 1 FROM skolenza."InstitutionEnabledModule" existing
      WHERE existing."InstitutionId" = enabled."InstitutionId" AND existing."ModuleId" = child."Id"
  );

INSERT INTO skolenza."InstitutionEnabledOperation"
    ("InstitutionId", "ModuleId", "OperationId", "IsOperationUsed", "IsEnabled", "AddedById", "AddedDateTime")
SELECT enabled."InstitutionId", enabled."ModuleId", mapping."OperationId", TRUE, TRUE, enabled."AddedById", CURRENT_TIMESTAMP
FROM skolenza."InstitutionEnabledModule" enabled
JOIN skolenza."Module" module ON module."Id" = enabled."ModuleId" AND module."ModuleCode" = 'INSTITUTION_EMAIL_TEMPLATE'
JOIN skolenza."ModuleOperationMapping" mapping ON mapping."ModuleId" = enabled."ModuleId" AND mapping."IsActive" = TRUE
WHERE NOT EXISTS
(
    SELECT 1 FROM skolenza."InstitutionEnabledOperation" existing
    WHERE existing."InstitutionId" = enabled."InstitutionId" AND existing."ModuleId" = enabled."ModuleId"
      AND existing."OperationId" = mapping."OperationId"
);

COMMIT;
